"""Root URL configuration (generated by Shikshya)."""
from django.conf import settings
from django.contrib import admin
from django.http import FileResponse, Http404, JsonResponse
from django.urls import include, path, re_path
from django.views.static import serve


def health_check(request):
    """Alive (config.middleware.HealthCheckMiddleware answers first; this route keeps the path in the URL map)."""
    return JsonResponse({"status": "ok"})


def frontend(request):
    """The built React app for every path that is not the API, the admin, health, static or media."""
    index = settings.FRONTEND_BUILD_DIR / "index.html"
    if not index.exists():
        raise Http404("The frontend is not built here (previews serve it with Vite).")
    return FileResponse(open(index, "rb"), content_type="text/html")


urlpatterns = [
    path('admin/', admin.site.urls),
    path('api/', include('api.urls')),
    path('health/', health_check, name='health'),
    re_path(r'^media/(?P<path>.*)$', serve, {'document_root': settings.MEDIA_ROOT}),
    re_path(r'^(?!api/|admin/|health/|media/|static/).*$', frontend, name='frontend'),
]
